def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    marker = min((x for x in counts if x not in (0, 1)), key=lambda x: counts[x])
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]

    # The repeated shape is placed only over the color underlying the marked shape.
    under = Counter()
    for r, c in pts:
        for dr, dc in ((-1,0),(1,0),(0,-1),(0,1)):
            rr, cc = r+dr, c+dc
            if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] != marker:
                under[grid[rr][cc]] += 1
    target = under.most_common(1)[0][0] if under else 0

    out = [row[:] for row in grid]
    for dr in range(-h, h):
        for dc in range(-w, w):
            if not (dr or dc):
                continue
            dest = [(r+dr, c+dc) for r,c in pts]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == target
                   for r,c in dest):
                for r,c in dest:
                    out[r][c] = marker
    return out
